WITH lines AS (SELECT id, level, latency_ms, status_code, attr_key, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS attr_key, value) SELECT id, level, latency_ms, status_code, attr_key, value, CUME_DIST() OVER (PARTITION BY level ORDER BY latency_ms DESC NULLS FIRST) AS latency_ms_cume_dist, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY level), 4) AS latency_ms_share, CORR(latency_ms, status_code) OVER (PARTITION BY attr_key) AS corr_latency_ms_status_code, CORR(latency_ms, status_code) OVER w_running AS corr_latency_ms_status_code_2 FROM lines WHERE latency_ms = 2083 WINDOW w_running AS (PARTITION BY level, attr_key);
